{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "LCS1269, a complex heteroaromatic kinase inhibitor, is predicted to have human intestinal absorption consistent with >30% bioavailability, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "CP-409,092, an amide-linked heteroaromatic kinase inhibitor, showed 69% relative oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Tolfenamic acid had an absolute oral bioavailability of 55.6% in healthy volunteers, demonstrating that lipophilic aromatic drugs with an anthranilic acid/amide motif are well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Tenoxicam, a heteroaromatic amide/enol drug, is essentially 100% orally bioavailable in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Bromazepam, a pyridine-containing heteroaromatic drug, has an absolute oral bioavailability of 86% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Vonoprazan, a pyridine-containing drug, has an estimated human oral bioavailability of 36%, above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Chlorpheniramine, although described as low bioavailability, has human values of 25-50%, all above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Labetalol, the lowest-bioavailability analogue, has a mean absolute oral bioavailability of about 30% in normal subjects, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "One labetalol study reported oral bioavailability of 4-17% (mean 9%), below threshold, but this is an outlier attributed to extensive first-pass metabolism and is not representative of the query's scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable evidence supports F≥20%: human absolute/relative F values for close analogues range from about 25-36% (chlorpheniramine, sulpiride, vonoprazan, labetalol mean) to 55-100% (tolfenamic acid, tenoxicam, isoniazid, bromazepam, CP-409,092). The query's amide/heteroaromatic kinase-inhibitor features are represented by high-F analogues; the single sub-20 labetalol outlier reflects first-pass metabolism not shared by the query. Therefore predict high.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the query molecule.",
    "Some records are predicted HIA or relative bioavailability rather than absolute F.",
    "Solubility-limited absorption and first-pass metabolism of the specific thioether/indazole scaffold are not directly tested."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "not_applicable",
      "card_ids": [],
      "decision_effect": "no_change",
      "direction": "neutral_or_unclear",
      "family": "none"
    }
  ],
  "revision_action": "initial"
}

